// 令牌桶限流器：用显式时间轴驱动（不读墙钟），保证输出确定
function createBucket(capacity, refillPerSec) {
  let tokens = capacity;
  let lastRefillAt = 0;
  let now = 0;
  return {
    advance(ms) { now += ms; },
    refill() {
      const deltaSec = (now - lastRefillAt) / 1000;
      const added = deltaSec * refillPerSec;
      if (added > 0) {
        tokens = Math.min(capacity, tokens + added);
        lastRefillAt = now;
      }
    },
    tryConsume() {
      this.refill();
      const allowed = tokens >= 1;
      if (allowed) tokens -= 1;
      return { allowed: allowed, left: Math.round(tokens * 1000) / 1000, t: now };
    },
    state() { return { tokens: Math.round(tokens * 1000) / 1000, now: now }; },
  };
}

function line(tag, i, r) {
  return '  ' + tag + '#' + i + ' t=' + String(r.t).padEnd(5) + 'ms allowed=' + String(r.allowed).padEnd(6)
    + 'tokens_left=' + r.left;
}

// 场景 1：容量 3、每秒补 1 —— 瞬时打 5 个请求
console.log('scenario1_burst: capacity=3 refill=1/s, 5 requests at t=0');
const b1 = createBucket(3, 1);
let allowed1 = 0;
for (let i = 1; i <= 5; i++) {
  const r = b1.tryConsume();
  if (r.allowed) allowed1 += 1;
  console.log(line('req', i, r));
}
console.log('  allowed=' + allowed1 + ' refused=' + (5 - allowed1));
console.log('  capacity_limits_burst=' + (allowed1 === 3));

// 场景 2：同配置，每秒一个请求 —— 全部放行
console.log('scenario2_steady: 5 requests spaced 1000ms');
const b2 = createBucket(3, 1);
let allowed2 = 0;
for (let i = 1; i <= 5; i++) {
  if (i > 1) b2.advance(1000);
  const r = b2.tryConsume();
  if (r.allowed) allowed2 += 1;
  console.log(line('req', i, r));
}
console.log('  allowed=' + allowed2 + ' all_allowed=' + (allowed2 === 5));

