console.log('scenario3_burst_then_decay: capacity=2 refill=4/s, 100 requests spaced 50ms');
const b3 = createBucket(2, 4);
const allowedFlags = [];
for (let i = 1; i <= 100; i++) {
  if (i > 1) b3.advance(50);
  allowedFlags.push(b3.tryConsume().allowed);
}
