const firstWindow = allowedFlags.slice(0, 20).filter(Boolean).length;
const secondWindow = allowedFlags.slice(20).filter(Boolean).length;
const firstSeconds = (20 - 1) * 50 / 1000;
const secondSeconds = (100 - 20) * 50 / 1000;
const firstRate = Math.round((firstWindow / firstSeconds) * 1000) / 1000;
const secondRate = Math.round((secondWindow / secondSeconds) * 1000) / 1000;
